void test_telemetry_01(void)
{
    sensors_snapshot_t readings = {0};
    readings.climate_valid = true;
    readings.temperature_c = 23.4567F;
    readings.humidity_percent = 50.0F;
    readings.acceleration_valid = true;
    readings.acceleration.x_g = -1.2349F;
    readings.acceleration.y_g = 0.0F;
    readings.acceleration.z_g = 1.5F;

    telemetry_process(1000U, &readings, RIDE_NONE);

    TEST_ASSERT_EQUAL_INT(1, (int)telemetry_calls);
    TEST_ASSERT_EQUAL_INT(23456, (int)record_field(4U));
    TEST_ASSERT_EQUAL_INT(50000, (int)record_field(5U));
    TEST_ASSERT_EQUAL_INT(-1234, (int)record_field(7U));
    TEST_ASSERT_EQUAL_INT(0, (int)record_field(8U));
    TEST_ASSERT_EQUAL_INT(1500, (int)record_field(9U));
}

